        try:
            parts = path.split('.')
            value = context
            for part in parts:
                if isinstance(value, dict):
                    value = value[part]
                elif isinstance(value, list):
                    if part.isdigit():
                        value = value[int(part)]
                    else:
                        return None
                else:
                    return None
            return str(value) if value is not None else ''
        except (KeyError, IndexError, AttributeError):
            return ''

